<?php
namespace App\Http\Controllers; use App\Models\Supplier; use Illuminate\Http\Request;
class SupplierController extends Controller { public function index(){return view('inventory.suppliers',['suppliers'=>Supplier::withCount('inventoryItems')->orderBy('name')->paginate(15)]);} public function store(Request $r){Supplier::create($this->data($r));return back()->with('success','Supplier added.');} public function update(Request $r,Supplier $supplier){$supplier->update($this->data($r));return back()->with('success','Supplier updated.');} public function destroy(Supplier $supplier){if($supplier->inventoryItems()->exists())return back()->with('error','Supplier is linked to inventory items.');$supplier->delete();return back()->with('success','Supplier deleted.');} private function data(Request $r){return $r->validate(['name'=>'required|string|max:120','contact_person'=>'nullable|string|max:120','phone'=>'nullable|string|max:30','email'=>'nullable|email|max:150','address'=>'nullable|string']);} }
